using System;
using System.Collections.Generic;
using System.Linq;
class Program {
    // Time O(N) to learn, O(V^2) space for V distinct words
    static void Main() {
        string text = "the cat sat on the mat the cat ate the fish";
        var words = text.Split(' ');
        var next = new Dictionary<string, Dictionary<string, int>>();
        // Learn: count which word follows which word
        for (int i = 0; i + 1 < words.Length; i++) {
            if (!next.ContainsKey(words[i])) next[words[i]] = new Dictionary<string, int>();
            next[words[i]].TryGetValue(words[i + 1], out int n);
            next[words[i]][words[i + 1]] = n + 1;
        }
        Console.WriteLine("Training text: " + text);
        string cur = "the";
        var output = new List<string> { cur };
        // Generate: repeatedly pick the most likely next word
        for (int k = 0; k < 4; k++) {
            cur = next[cur].OrderByDescending(p => p.Value).ThenBy(p => p.Key).First().Key;
            output.Add(cur);
        }
        Console.WriteLine("Generated: " + string.Join(" ", output));
    }
}

using System;
class Program {
    // Rough rule: 1 token is about 4 characters of English text
    // Time O(1), space O(1)
    static int EstimateTokens(string s) => (int)Math.Ceiling(s.Length / 4.0);
    static void Main() {
        string prompt = "Summarise this ticket in 3 bullet points for a support manager.";
        string code = "public static int Add(int a, int b) { return a + b; }";
        double pricePerMillionInput = 3.00; // placeholder price in dollars
        foreach (var text in new[] { prompt, code }) {
            int tokens = EstimateTokens(text);
            // cost = tokens x price per token
            double cost = tokens * pricePerMillionInput / 1_000_000.0;
            Console.WriteLine("Text: " + text);
            Console.WriteLine("  chars=" + text.Length + " estimated tokens=" + tokens + " cost=$" + cost.ToString("F6"));
        }
        // 1000 calls a day with the first prompt, for 30 days
        long monthly = 1000L * 30 * EstimateTokens(prompt);
        Console.WriteLine("Monthly input tokens for 1000 calls/day: " + monthly);
    }
}

using System;
class Program {
    // Time O(1), space O(1)
    static int Tokens(int chars) => (chars + 3) / 4;
    static void Main() {
        int window = 8000;          // model context window in tokens
        int maxOutput = 1000;       // room we reserve for the reply
        int system = Tokens(2000), history = Tokens(14000), docs = Tokens(12000);
        int input = system + history + docs;
        Console.WriteLine("system=" + system + " history=" + history + " docs=" + docs);
        Console.WriteLine("input=" + input + " + reply " + maxOutput + " = " + (input + maxOutput) + " of " + window);
        // Everything plus the reply must fit on the "desk"
        if (input + maxOutput > window) {
            int over = input + maxOutput - window;
            Console.WriteLine("Too big by " + over + " tokens: trim history or retrieve fewer chunks");
        } else {
            Console.WriteLine("Fits");
        }
    }
}

using System;
using System.Linq;
class Program {
    // Softmax with temperature. Time O(V), space O(V) for V candidate tokens
    static double[] Probs(double[] logits, double t) {
        // divide scores by temperature, then turn into probabilities
        var e = logits.Select(l => Math.Exp(l / t)).ToArray();
        double sum = e.Sum();
        return e.Select(x => x / sum).ToArray();
    }
    static void Main() {
        string[] tokens = { "Paris", "Lyon", "banana" };
        double[] logits = { 2.0, 1.0, 0.0 };
        Console.WriteLine("Candidates: " + string.Join(", ", tokens));
        foreach (double t in new[] { 0.2, 1.0, 2.0 }) {
            var p = Probs(logits, t);
            // low temperature: one token dominates; high: choices flatten out
            Console.WriteLine("T=" + t.ToString("F1") + " -> " +
                string.Join("  ", p.Select(x => x.ToString("F3"))));
        }
    }
}

using System;
using System.Linq;
class Program {
    // Time O(C*S*W) for C claims, S sources, W words; space O(W)
    static void Main() {
        string[] sources = {
            "Refunds are accepted within 30 days of purchase.",
            "Shipping to Europe takes 5 working days." };
        string[] answer = {
            "Refunds are accepted within 30 days.",
            "Refunds are paid in cash at any store." };
        foreach (var claim in answer) {
            var words = claim.ToLower().TrimEnd('.').Split(' ');
            // share of the claim's words found in the best matching source
            double best = sources.Max(s => words.Count(w => s.ToLower().Contains(w)) / (double)words.Length);
            // low overlap means the claim is probably not supported
            Console.WriteLine(claim + " -> support " + best.ToString("F2") +
                (best >= 0.8 ? " OK" : " UNSUPPORTED, flag it"));
        }
    }
}

using System;
using System.Collections.Generic;
class Program {
    // Each call sends ALL earlier turns. Total cost grows O(N^2) in turns; space O(N)
    static void Main() {
        var history = new List<string>();
        int totalSent = 0;
        string[] userTurns = { "Hi", "My order is 1042", "Where is it?", "Thanks" };
        for (int turn = 1; turn <= userTurns.Length; turn++) {
            history.Add("user: " + userTurns[turn - 1]);
            // the "request" is the whole stored history, not just the new message
            int words = 0;
            foreach (var m in history) words += m.Split(' ').Length;
            totalSent += words;
            Console.WriteLine("Turn " + turn + ": sent " + history.Count + " messages, " + words + " words");
            history.Add("assistant: (reply " + turn + ")");   // app stores the reply too
        }
        Console.WriteLine("Total words sent over 4 turns: " + totalSent);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
class Program {
    // Time O(N), space O(N)
    static List<string> Trim(string system, List<string> turns, int budgetWords) {
        var kept = new List<string>();
        int used = system.Split(' ').Length;
        // walk from the newest turn backwards until the budget is full
        for (int i = turns.Count - 1; i >= 0; i--) {
            int w = turns[i].Split(' ').Length;
            if (used + w > budgetWords) break;
            kept.Insert(0, turns[i]);
            used += w;
        }
        kept.Insert(0, system);   // system prompt is always kept
        return kept;
    }
    static void Main() {
        var turns = new List<string> { "u: hello there", "a: hi, how can I help", "u: my order 1042 is late", "a: checking order 1042 now", "u: any news" };
        Console.WriteLine("Full history: " + turns.Count + " turns");
        var kept = Trim("SYSTEM: be brief", turns, 14);
        Console.WriteLine("Kept: " + string.Join(" | ", kept));
    }
}

