    record Candidate(string Name, double PassRate, double CostPer1000, int LatencyMs);
    // Time O(M log M) for M models, space O(M)
    static void Main() {
        var models = new[] {
            new Candidate("small", 0.88, 0.40, 600),
            new Candidate("medium", 0.94, 2.50, 1200),
            new Candidate("large", 0.96, 15.00, 2500) };
