using System;
using System.Collections.Generic;
using System.Text.Json;
class Program {
    static readonly string[] Allowed = { "BILLING", "DELIVERY", "BUG" };
    // Time O(L) for reply length L, space O(L)
    static bool TryParse(string json, out string category, out string error) {
        category = null; error = null;
        try {
            using var doc = JsonDocument.Parse(json);
            category = doc.RootElement.GetProperty("category").GetString();
            // JSON is valid, but is the value one we allow?
            if (Array.IndexOf(Allowed, category) < 0) { error = "bad category " + category; return false; }
            return true;
        } catch (Exception e) when (e is JsonException || e is KeyNotFoundException) {
            error = e.Message; return false;
        }
    }
    static void Main() {
        string[] replies = { "Sure! Here you go: {\"category\":\"BUG\"}", "{\"category\":\"refund\"}", "{\"category\":\"BILLING\"}" };
        foreach (var r in replies) {
            bool ok = TryParse(r, out var cat, out var err);
            Console.WriteLine(r + " -> " + (ok ? "OK " + cat : "REJECT (" + (err.Length > 30 ? err.Substring(0, 30) : err) + ")"));
        }
    }
}

using System;
