class Program {
    // Time O(L*P) for text length L and P placeholders, space O(L)
    static readonly Dictionary<string, string> Registry = new Dictionary<string, string> {
        ["summarise.v1"] = "Summarise {text} in {n} bullets.",
        ["summarise.v2"] = "Summarise the text below in {n} bullets for {audience}.\nText: {text}" };
    static string Render(string id, Dictionary<string, string> values) {
        string t = Registry[id];
        // fill each named slot; the user text only ever goes into a slot
        foreach (var kv in values) t = t.Replace("{" + kv.Key + "}", kv.Value);
        return t;
    }
    static void Main() {
        var v = new Dictionary<string, string> { ["n"] = "3", ["audience"] = "managers", ["text"] = "Order 1042 was late." };
        foreach (var id in new[] { "summarise.v1", "summarise.v2" })
            Console.WriteLine("[" + id + "] " + Render(id, v).Replace("\n", " / "));
        // log the id on every call so a bad answer can be traced to a version
    }
}

using System;
class Program {
    // Time O(L), space O(1)
    static int SharedPrefix(string a, string b) {
        int i = 0;
        while (i < a.Length && i < b.Length && a[i] == b[i]) i++;   // stop at first difference
        return i;
    }
    static void Main() {
        string rules = "RULES: be brief. Answer about orders only.\n";
        // Layout A: stable rules first, changing question last
        string a1 = rules + "Question: where is order 1042?";
        string a2 = rules + "Question: how do I return item 77?";
        // Layout B: changing date first breaks the prefix
        string b1 = "Date: 2026-05-01\n" + rules + "Question: where is order 1042?";
        string b2 = "Date: 2026-05-02\n" + rules + "Question: how do I return item 77?";
        Console.WriteLine("Layout A reusable prefix: " + SharedPrefix(a1, a2) + " chars of " + a1.Length);
        Console.WriteLine("Layout B reusable prefix: " + SharedPrefix(b1, b2) + " chars of " + b1.Length);
    }
}

using System;
class Program {
    // Cosine similarity. Time O(D) for D dimensions, space O(1)
    static double Cosine(double[] a, double[] b) {
        double dot = 0, na = 0, nb = 0;
        for (int i = 0; i < a.Length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
        return dot / (Math.Sqrt(na) * Math.Sqrt(nb));
    }
    static void Main() {
        // tiny made-up 3-number "embeddings" (real ones have hundreds of numbers)
        var refund = new[] { 0.9, 0.1, 0.0 };     // "refund policy"
        var money  = new[] { 0.8, 0.2, 0.1 };     // "how do I get my money back"
        var pizza  = new[] { 0.0, 0.1, 0.9 };     // "best pizza recipe"
        Console.WriteLine("refund vs money back: " + Cosine(refund, money).ToString("F3"));
        // close to 1 = similar meaning, close to 0 = unrelated
        Console.WriteLine("refund vs pizza:      " + Cosine(refund, pizza).ToString("F3"));
    }
}

using System;
using System.Linq;
class Program {
    static double Cosine(double[] a, double[] b) {
        double d = 0, x = 0, y = 0;
        for (int i = 0; i < a.Length; i++) { d += a[i] * b[i]; x += a[i] * a[i]; y += b[i] * b[i]; }
        return d / Math.Sqrt(x * y);
    }
    // Time O(N*D) for N vectors of D numbers, space O(N); real databases use an index
    static void Main() {
        var docs = new (string Text, double[] Vec)[] {
            ("Refund within 30 days", new[] { 0.9, 0.1, 0.0 }),
            ("Shipping takes 5 days", new[] { 0.1, 0.9, 0.1 }),
            ("Pizza recipe", new[] { 0.0, 0.1, 0.9 }) };
        var query = new[] { 0.8, 0.3, 0.0 };   // embedding of "get my money back"
        // score every item, sort best first, keep k
        var top = docs.Select(d => (d.Text, Score: Cosine(query, d.Vec)))
                      .OrderByDescending(x => x.Score).Take(2);
        foreach (var t in top) Console.WriteLine(t.Score.ToString("F3") + "  " + t.Text);
    }
}

