    }
}

using System;
using System.Collections.Generic;
using System.Linq;
class Program {
    // Time O(W) for W words, space O(W)
    static List<string> Chunk(string text, int size, int overlap) {
        var words = text.Split(' ');
        var chunks = new List<string>();
        // step forward by (size - overlap) so neighbours share some words
        for (int start = 0; start < words.Length; start += size - overlap) {
            chunks.Add(string.Join(" ", words.Skip(start).Take(size)));
            if (start + size >= words.Length) break;
        }
        return chunks;
    }
    static void Main() {
        string text = "Refunds apply after purchase. It applies within 30 days. Sale items are excluded. Contact support for help";
        var chunks = Chunk(text, 8, 2);
        Console.WriteLine("Words: " + text.Split(' ').Length + ", chunks: " + chunks.Count);
        for (int i = 0; i < chunks.Count; i++) Console.WriteLine("[" + i + "] " + chunks[i]);
    }
}

using System;
using System.Linq;
class Program {
    // Time O(D) per comparison, space O(D)
    static double[] Normalize(double[] v) {
        double len = Math.Sqrt(v.Sum(x => x * x));
        return v.Select(x => x / len).ToArray();    // make length 1
    }
    static double Dot(double[] a, double[] b) => a.Zip(b, (x, y) => x * y).Sum();
    static void Main() {
        var a = Normalize(new[] { 3.0, 4.0, 0.0 });
        var b = Normalize(new[] { 4.0, 3.0, 1.0 });
        double dot = Dot(a, b);
        double dist = Math.Sqrt(a.Zip(b, (x, y) => (x - y) * (x - y)).Sum());
        Console.WriteLine("dot product (= cosine for unit vectors): " + dot.ToString("F4"));
        Console.WriteLine("euclidean distance: " + dist.ToString("F4"));
        // for unit vectors: dist^2 = 2 - 2*dot, so all three rank results the same way
        Console.WriteLine("check 2-2*dot = " + (2 - 2 * dot).ToString("F4") + ", dist^2 = " + (dist * dist).ToString("F4"));
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
class Program {
    // Time O(L log L) for L total results, space O(L)
    static void Main() {
        var keyword = new[] { "doc-B", "doc-A", "doc-D" };   // ranked by keyword search
        var vector  = new[] { "doc-A", "doc-C", "doc-B" };   // ranked by vector search
        var score = new Dictionary<string, double>();
        foreach (var list in new[] { keyword, vector })
            for (int rank = 0; rank < list.Length; rank++) {
                // each list gives 1/(60+rank); documents high in both lists win
                score.TryGetValue(list[rank], out double s);
                score[list[rank]] = s + 1.0 / (60 + rank + 1);
            }
        Console.WriteLine("Keyword: " + string.Join(",", keyword));
        Console.WriteLine("Vector:  " + string.Join(",", vector));
        foreach (var kv in score.OrderByDescending(k => k.Value))
            Console.WriteLine(kv.Key + " " + kv.Value.ToString("F5"));
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
class Program {
    record Chunk(string Text, string Tenant, string Group, double Score);
    // Time O(N log N), space O(N); in a real DB the filter runs inside the query
    static void Main() {
        var index = new List<Chunk> {
            new Chunk("Acme salary bands", "acme", "hr", 0.95),
            new Chunk("Acme travel policy", "acme", "all", 0.80),
            new Chunk("Globex travel policy", "globex", "all", 0.85) };
        // identity comes from the validated token, never from the request body
        string tenant = "acme"; var groups = new HashSet<string> { "all" };
        // filter FIRST, then rank, so forbidden text can never reach the prompt
        var allowed = index.Where(c => c.Tenant == tenant && groups.Contains(c.Group))
                           .OrderByDescending(c => c.Score);
        foreach (var c in allowed) Console.WriteLine("allowed: " + c.Text);
        Console.WriteLine("blocked: " + (index.Count - allowed.Count()) + " chunk(s)");
    }
}

