using System;
class Program {
    // Time O(S) for S steps, space O(1); the cap makes cost bounded
    static string FakeModel(int step) {
        // stand-in for the model: asks for tools twice, then answers
        if (step == 1) return "TOOL:search";
        if (step == 2) return "TOOL:calculate";
        return "DONE:The answer is 42";
    }
    static void Main() {
        int maxSteps = 5;                 // hard stop so it cannot loop forever
        for (int step = 1; step <= maxSteps; step++) {
            string decision = FakeModel(step);
            Console.WriteLine("Step " + step + ": model chose " + decision);
            if (decision.StartsWith("DONE:")) {
                Console.WriteLine("Final: " + decision.Substring(5));
                return;                   // the model decided it is finished
            }
            // here the app would run the tool and add the result to the chat
        }
        Console.WriteLine("Stopped: step limit reached, hand over to a human");
    }
}

using System;
using System.Collections.Generic;
class Program {
    // owner of each order; in real life this is a database lookup
    static readonly Dictionary<int, string> Owners = new Dictionary<int, string> { [1042] = "alice", [2001] = "bob" };
    // Time O(1), space O(1)
    static string GetOrder(string userFromToken, int orderId) {
        if (orderId <= 0 || orderId > 999999) return "error: invalid id";       // validate shape
        if (!Owners.TryGetValue(orderId, out var owner)) return "error: not found";  // reject invented ids
        // authorise with the signed-in user, never with a user id the model supplied
        if (owner != userFromToken) return "error: not allowed";
        return "order " + orderId + ": shipped";
    }
    static void Main() {
        foreach (var id in new[] { 1042, 2001, 77, -5 })
            Console.WriteLine("alice asks for " + id + " -> " + GetOrder("alice", id));
    }
}

using System;
class Program {
    // Time O(S) for S steps, space O(1)
    static void Main() {
        double perStep = 0.95;     // each step is right 95% of the time
        Console.WriteLine("Per-step success: " + perStep);
        foreach (int steps in new[] { 1, 3, 5, 10, 20 }) {
            // all steps must be right, so multiply the chances
            double all = Math.Pow(perStep, steps);
            Console.WriteLine(steps.ToString().PadLeft(2) + " steps -> " + all.ToString("P1") + " end to end");
        }
        // with a check after each step that catches 80% of errors:
        double withChecks = Math.Pow(perStep + (1 - perStep) * 0.8, 10);
        Console.WriteLine("10 steps with checks -> " + withChecks.ToString("P1"));
    }
}

using System;
using System.Linq;
using System.Text.Json;
class Program {
    static readonly string[] Allowed = { "BILLING", "DELIVERY", "BUG" };
    // Time O(C*L) for C cases of reply length L, space O(1)
    static bool Check(string reply, string expected) {
        try {
            using var doc = JsonDocument.Parse(reply);                  // property 1: valid JSON
            string cat = doc.RootElement.GetProperty("category").GetString();
            return Allowed.Contains(cat) && cat == expected;            // property 2: allowed and right
        } catch { return false; }
    }
    static void Main() {
        var cases = new[] {
            ("{\"category\":\"BILLING\"}", "BILLING"),
            ("{\"category\":\"DELIVERY\"}", "BILLING"),
            ("not json", "BUG"),
            ("{\"category\":\"BUG\"}", "BUG") };
        int pass = cases.Count(c => Check(c.Item1, c.Item2));
        Console.WriteLine("Passed " + pass + " of " + cases.Length + " = " + (100.0 * pass / cases.Length).ToString("F0") + "%");
    }
}

