        Console.WriteLine("SendEmail after approval -> " + Decide("SendEmail", true));
    }
}

using System;
using System.Text.RegularExpressions;
class Program {
    // Time O(L) for text length L, space O(L)
    static string Mask(string text) {
        // replace e-mail addresses and long digit runs (card or phone numbers)
        text = Regex.Replace(text, @"[\w.+-]+@[\w-]+\.[\w.]+", "[EMAIL]");
        text = Regex.Replace(text, @"\b\d[\d -]{8,}\d\b", "[NUMBER]");
        return text;
    }
    static void Main() {
        string input = "Contact anna@example.com or call 0612 345 6789 about card 4111 1111 1111 1111.";
        Console.WriteLine("Before: " + input);
        Console.WriteLine("After:  " + Mask(input));
        // regex catches common formats only; names need an entity-recognition service
    }
}

