using System;
class Program {
    static int calls = 0;
    // fake provider: throttles the first two calls
    static int FakeCall() { calls++; return calls <= 2 ? 429 : 200; }
    // Time O(R) for R retries, space O(1)
    static void Main() {
        var rng = new Random(7);
        int maxRetries = 4;
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            int status = FakeCall();
            Console.WriteLine("Attempt " + (attempt + 1) + " -> HTTP " + status);
            if (status == 200) { Console.WriteLine("Success"); return; }
            // exponential cap: 1s, 2s, 4s, 8s ...; jitter picks a random time up to the cap
            double cap = Math.Pow(2, attempt);
            double wait = rng.NextDouble() * cap;
            Console.WriteLine("  would wait up to " + cap.ToString("F0") + " s (random pick below the cap)");
            if (wait < 0) break;
        }
        Console.WriteLine("Total calls made: " + calls);
    }
}
